/// <remarks>A TypeScript interface: it has no runtime value of its own, so it binds as a plain object.</remarks>
[JsGlobal("Object")]
public interface WebGL2RenderingContextBase
{
    /// <summary>[MDN Reference](https://developer.mozilla.org/docs/Web/API/WebGL2RenderingContext/beginQuery)</summary>
    void BeginQuery(double target, WebGLQuery query);

    /// <summary>[MDN Reference](https://developer.mozilla.org/docs/Web/API/WebGL2RenderingContext/beginTransformFeedback)</summary>
    void BeginTransformFeedback(double primitiveMode);

    /// <summary>[MDN Reference](https://developer.mozilla.org/docs/Web/API/WebGL2RenderingContext/bindBufferBase)</summary>
    void BindBufferBase(double target, double index, WebGLBuffer? buffer);

    /// <summary>[MDN Reference](https://developer.mozilla.org/docs/Web/API/WebGL2RenderingContext/bindBufferRange)</summary>
    void BindBufferRange(double target, double index, WebGLBuffer? buffer, double offset, double size);

    /// <summary>[MDN Reference](https://developer.mozilla.org/docs/Web/API/WebGL2RenderingContext/bindSampler)</summary>
    void BindSampler(double unit, WebGLSampler? sampler);

    /// <summary>[MDN Reference](https://developer.mozilla.org/docs/Web/API/WebGL2RenderingContext/bindTransformFeedback)</summary>
    void BindTransformFeedback(double target, WebGLTransformFeedback? tf);

    /// <summary>[MDN Reference](https://developer.mozilla.org/docs/Web/API/WebGL2RenderingContext/bindVertexArray)</summary>
    void BindVertexArray(WebGLVertexArrayObject? array);

    /// <summary>[MDN Reference](https://developer.mozilla.org/docs/Web/API/WebGL2RenderingContext/blitFramebuffer)</summary>
    void BlitFramebuffer(double srcX0, double srcY0, double srcX1, double srcY1, double dstX0, double dstY0, double dstX1, double dstY1, double mask, double filter);

    /// <summary>[MDN Reference](https://developer.mozilla.org/docs/Web/API/WebGL2RenderingContext/clearBuffer)</summary>
    void ClearBufferfi(double buffer, double drawbuffer, double depth, double stencil);

